import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:rotolo_ai_assistant/core/data_quality.dart';
import 'package:rotolo_ai_assistant/models/json.dart';
import 'package:rotolo_ai_assistant/models/payloads.dart';
import 'package:rotolo_ai_assistant/models/report.dart';
import 'package:rotolo_ai_assistant/state/view_models.dart';

/// The report the n8n workflow "RE - APP - Daily Operations Report" produces
/// (generated by n8n/test/run_nodes.mjs from sample sub-workflow outputs).
void main() {
  final json = asMap(jsonDecode(File('n8n/test/sample_report.json').readAsStringSync()))..['id'] = 'live-1';
  final report = Report.fromJson(json, isLatest: true);

  test('every section parses and is labelled live, not synthetic', () {
    expect(report.summary.dataMode, 'live');
    expect(report.sections.keys, containsAll(SectionSource.values));
    for (final s in report.sections.values) {
      final flags = qualityFlags(
          dataMode: s.dataMode, status: s.status, collectedAt: s.collectedAt,
          now: DateTime.utc(2026, 11, 20, 15), staleAfterHours: 26, isLatest: true);
      expect(flags, isNot(contains(QualityFlag.synthetic)), reason: s.source.key);
    }
    expect(report[SectionSource.emailEvidence]!.status, 'partial');
  });

  test('money arrives in cents; missing balances stay null', () {
    final rent = RentPayload(report[SectionSource.doorloopRent]!.payload);
    expect(rent.leases.first.apiBalance.totalDue, 145007);
    expect(rent.leases[1].apiBalance.totalDue, isNull);
    expect(LeaseView(rent.leases[1]).needsReview, isTrue);
    expect(rent.payments.single.amount, 75010);
  });

  test('staff activity distinguishes a confirmed zero from a missing total', () {
    final empty = StaffActivityPayload({
      'activity_status': 'no_activity',
      'team_total': {'tracked_sec': 0},
      'users': [{'tracked_sec': 0}],
    });
    expect(empty.noActivity, isTrue);
    expect(empty.trackedSec, 0);

    final incomplete = StaffActivityPayload({
      'users': [{'tracked_sec': 3600}, {'tracked_sec': null}],
    });
    expect(incomplete.noActivity, isFalse);
    expect(incomplete.trackedSec, isNull);
    expect(StaffActivityPayload({}).trackedSec, isNull);

    final historical = StaffActivityPayload({
      'users': [{'tracked_sec': 3600}, {'tracked_sec': 7200}],
    });
    expect(historical.trackedSec, 10800);
  });

  test('tasks, deals and evidence map onto the app views', () {
    final today = DateTime(2026, 11, 20);
    final tasks = TasksPayload(report[SectionSource.doorloopTasks]!.payload).tasks.map((t) => TaskView(t, null, today)).toList();
    expect(tasks.first.overdue, isTrue);
    expect(tasks.first.priority.$1, 'High');
    expect(tasks.first.assignee, 'Assignee not returned');
    expect(tasks[1].claimed, isTrue);
    final ev = EmailEvidencePayload(report[SectionSource.emailEvidence]!.payload);
    final deals = DealsPayload(report[SectionSource.fubDeals]!.payload).deals;
    expect(deals.map((d) => d.id), [101, 102]);
    expect(ev.itemsFor(101).single.subject, '12 Main St - title');
    expect(ev.mailboxVerified, isTrue);
    expect(StaffActivityPayload(report[SectionSource.timeDoctor]!.payload).users.first.trackedSec, 28800);
  });
}
